// Deutsche Übersetzungen der Aktivitäten (Schweizer Schreibweise, nach id)
const TR_DE = {
"pate-sel":{t:"Salzteig selber machen",desc:"Drei Zutaten aus dem Vorratsschrank: formen, backen, bemalen. Erinnerungen, die bleiben.",s:["2 Tassen Mehl, 1 Tasse feines Salz und 1 Tasse lauwarmes Wasser mischen.","Zu einem geschmeidigen Teig kneten (bei Bedarf Mehl zugeben).","Formen, ausstechen, ein Loch zum Aufhängen machen.","2 Std. bei 100 °C backen (oder 2 Tage trocknen lassen), dann bemalen."],v:{b:"Rohen Teig kneten und drücken, unter Aufsicht.",p:"Hand- und Blattabdrücke, Ausstechformen.",e:"Figuren, Kühlschrankmagnete, saisonale Deko."}},
"cabane":{t:"Deckenhöhle bauen",desc:"Stühle, Leintücher und Kissen: das Wohnzimmer wird zum geheimen Lager.",s:["Stühle, Leintücher, Decken, Wäscheklammern und Kissen sammeln.","Tücher zwischen Möbeln spannen, mit Klammern oder schweren Büchern fixieren.","Innen einrichten: Kissen, Taschenlampe, Bücher, Kuscheltiere.","Bonus: Zvieri oder Vorlesen in der Höhle."],v:{b:"Ein Tuch über dem Tisch: Guguseli garantiert.",p:"Höhle mit „Tür“ und Passwort.",e:"Zuerst einen Bauplan zeichnen, mehrere Räume bauen."}},
"tresor":{t:"Schatzsuche",desc:"Versteckte Hinweise, Rätsel und ein Schatz am Ende (ein Zvieri, ein Ausflug, ein kleines Geschenk).",s:["Schatz und finales Versteck wählen.","5 bis 8 Hinweise vorbereiten, jeder führt zum nächsten.","Hinweise vom Ende her verstecken.","Den ersten Hinweis geben… und suchen lassen!"],v:{p:"Hinweise als Zeichnungen („unter dem Bett“, „in der Badewanne“).",e:"Rätsel, Bilderrätsel, einfache Geheimschriften (umgekehrtes Alphabet).",a:"Escape-Version: Zahlenschlösser, Koordinaten, Logikrätsel."}},
"bateaux":{t:"Bootsregatta in Pfützen",desc:"Regen macht Pfützen zu Ozeanen! Boote basteln und in Pfützen und Rinnsalen fahren lassen.",s:["Boote basteln: Korkzapfen, Schalen, Nussschalen.","Ein Segel anbringen (Zahnstocher + Papier).","Gummistiefel und Regenjacke, ab zu den Pfützen!","Rennen: pusten, damit das Boot fährt."],v:{p:"Schale + Papiersegel, darauf pusten.",e:"Wettbewerb: Welches Boot trägt die meisten Steine, ohne zu sinken?"}},
"flaques":{t:"Grosser Pfützen-Hüpf-Ausflug",desc:"Gummistiefel, Regenjacke und los: springen, messen und dem Regen lauschen.",s:["Ausrüsten: Gummistiefel, Regenjacke, trockene Kleider für danach bereitlegen.","Die grösste Pfütze im Quartier suchen.","Wettbewerb um den grössten Platscher.","Zurück ins Warme mit einer heissen Schokolade."],v:{b:"Kleine Hüpfer an der Hand, den Regen spüren.",p:"Platsch-Wettbewerb und Regenwurmsuche.",e:"Pfützentiefe mit einem markierten Stock messen."}},
"bonhomme":{t:"Schneeskulpturen",desc:"Schneemann, Tiere, Burg: Schnee ist eine riesige Knetmasse.",s:["Warm anziehen (wasserdichte Handschuhe!).","Grosse Kugeln für die Basis rollen.","Mit Stöcken, Steinen, Rüebli und Schal dekorieren.","Erinnerungsfoto, dann heisse Schokolade."],v:{b:"Anfassen, Fussabdrücke im Schnee machen.",p:"Kleiner Schneemann und Schneeengel.",e:"Schneetiere; Schnee mit Wasser + Lebensmittelfarbe im Sprühfläschchen färben.",a:"Skulpturenwettbewerb oder Mini-Iglu aus Schneeziegeln (Behälter)."}},
"luge":{t:"Schlittelnachmittag",desc:"Schlitten, Bob oder sogar ein robuster Abfallsack: ab den Hang hinunter!",s:["Einen sicheren Hang ohne Strasse oder Hindernisse unten wählen.","Ausrüstung: Schlitten, Helm für die Kleinen, Thermosflasche.","Abwechselnd fahren, seitlich wieder hochlaufen.","Herausforderungen: längste Fahrt, Slalom zwischen Stöcken."],v:{p:"Kleiner Hang, auf dem Schoss eines Erwachsenen.",e:"Slalom, Zweier-Schlittenrennen.",a:"Schlittelbahn bauen, Zeiten stoppen."}},
"bataille-eau":{t:"Wasserschlacht mit Schwämmen",desc:"Schwämme, Kübel und Becher: die beste Abkühlung an einem heissen Tag.",s:["Kübel mit Wasser füllen, Schwämme zu „Bomben“ schneiden.","Teams bilden und Spielfeld abstecken.","Variante: Staffel mit dem löchrigen Becher (Flasche füllen).","Sonnencreme und Pausen im Schatten!"],v:{p:"Pflanzen giessen, umschütten, kleine Spritzer.",e:"Teamschlacht, Staffel mit löchrigem Becher.",a:"Fahnenklau mit Schwämmen: getroffen = raus."}},
"glacons":{t:"Gefrorene Schätze befreien",desc:"Figuren im Eis gefangen: mit Salz, warmem Wasser und Pinseln werden sie gerettet.",s:["Am Vorabend: kleine Spielsachen in einer Schale oder Gläsern mit Wasser einfrieren.","In eine grosse Schüssel stürzen.","Pipetten mit warmem Wasser, Salz, Pinsel und Löffel geben.","Beobachten, wie das Eis mit Salz schneller schmilzt."],v:{b:"Grosse Blöcke mit grossen Spielsachen (keine Kleinteile), Kälte spüren.",p:"Pipetten, Salz, farbiges Wasser."}},
"volcan":{t:"Vulkanausbruch",desc:"Natron + Essig = spektakulärer Schaumausbruch.",s:["Einen Kegel um ein kleines Glas formen (Salzteig, Papier oder draussen Sand).","2 Löffel Natron, Spülmittel und Lebensmittelfarbe hineingeben.","Essig dazugiessen und zurücktreten!","Erklären: Das Kohlendioxid lässt es schäumen."],v:{p:"Farbige Ausbrüche in einer Schale, immer wieder.",e:"Mengen testen: Welches Rezept macht den grössten Ausbruch?"}},
"herbier":{t:"Herbarium der Jahreszeiten",desc:"Sammelspaziergang, dann pressen, kleben und benennen.",s:["Spaziergang mit Tasche: Blätter, Blumen, Samen (keine geschützten Pflanzen ausreissen).","Einige Tage zwischen zwei Blättern in einem dicken Buch pressen.","In ein Heft kleben, Ort und Datum notieren.","Die Namen in einem Buch nachschlagen oder jemanden fragen."],v:{p:"Blätter-Collagen in Tierform.",e:"Herbarium nach Bäumen sortiert, Blattabriebe mit Farbstift.",a:"Wissenschaftliches Herbarium mit lateinischen Namen, oder Cyanotypie."}},
"landart":{t:"Land Art",desc:"Vergängliche Kunstwerke aus dem, was die Natur bietet.",s:["Steine, Stöcke, Blätter, Tannenzapfen sammeln.","Ein Thema wählen: Spirale, Mandala, Gesicht, Tier.","Am Boden gestalten, mit Farben spielen.","Ein Foto machen, bevor die Natur es zurückholt."],v:{p:"Gesichter und Sonnen aus Steinen.",e:"Riesige Mandalas, Farbverläufe mit Blättern.",a:"Steintürme im Gleichgewicht, inszenierte Fotos."}},
"mangeoire":{t:"Vogelfutterstelle",desc:"Tannenzapfen + Fett + Körner: Die Vögel kommen zu Besuch.",s:["Eine Schnur an einen Tannenzapfen binden.","Mit Pflanzenfett (oder ungesalzener Erdnussbutter) bestreichen.","In Körnern wälzen.","Vor einem Fenster aufhängen und die Besucher beobachten."],v:{p:"In Körnern wälzen, Vögel zählen.",e:"Ein Beobachtungsheft der Arten führen."}},
"pizza":{t:"Pizza-Werkstatt",desc:"Alle belegen ihre eigene Pizza (oder machen ein Gesicht aus den Zutaten).",s:["Teig machen oder kaufen, in Portionen teilen.","Beläge in Schüsseln bereitstellen.","Alle wallen aus und belegen ihre Pizza.","Backen durch Erwachsene, 12 Min. bei 230 °C."],v:{p:"Pizza-Gesicht mit Oliven und Peperoni.",e:"Teig selbst kneten, Zutaten abmessen.",a:"Pizza zu 100 % selbst gemacht, Sauce und Teig, Ofen im Griff."}},
"cookies":{t:"Riesen-Cookies",desc:"Wägen, mischen, Teig naschen: Backen ist Mathematik, die gut riecht.",s:["100 g weiche Butter, 100 g Zucker, 1 Ei mischen.","200 g Mehl, ½ Päckchen Backpulver, Schokoladenstückchen dazugeben.","Kugeln mit Abstand aufs Blech setzen.","10 bis 12 Min. bei 180 °C."],v:{p:"Einfüllen, mischen, Kugeln formen.",e:"Rezept lesen und selbst wägen.",a:"Eigenes Rezept erfinden und aufschreiben."}},
"brochettes":{t:"Regenbogen-Fruchtspiesse",desc:"Ein farbiges Zvieri, das Kinder selbst zubereiten (und essen!).",s:["Früchte waschen und schneiden (für die Kleinsten Erwachsene).","Nach Farben sortieren.","In Regenbogenreihenfolge auf Holzspiesse stecken.","Option: Spitze in geschmolzene Schokolade tauchen."],v:{b:"Weiche Stücke zum Greifen, Geschmäcker entdecken.",p:"Auf Trinkhalme oder stumpfe Spiesse stecken.",e:"Muster erfinden und vorher zeichnen."}},
"parcours-salon":{t:"Hindernisparcours im Wohnzimmer",desc:"Kissen, Stühle, Seile: ein Ninja-Parcours zum Austoben, auch bei Regen.",s:["Platz schaffen, Zerbrechliches wegräumen.","Stationen bauen: unter dem Tisch durchkriechen, über Kissen springen, auf einem Seil am Boden balancieren.","Jeden Durchgang stoppen.","Die Kinder neue Stationen erfinden lassen."],v:{b:"Kissentunnel zum Durchkrabbeln.",p:"Parcours mit einem Tier zum Nachahmen pro Station.",e:"Stoppuhr, Gleichgewichtsübungen, Familienrekorde."}},
"jeux-cour":{t:"Klassische Pausenplatzspiele",desc:"Ochs am Berg, Versteinerlis, Fischer, wie tief ist das Wasser: Spiele ohne Material, die immer funktionieren.",s:["Einen offenen Platz wählen (Park, Hof).","Die Regeln des Spiels erklären.","Rollen jede Runde wechseln.","3 verschiedene Spiele hintereinander spielen."],v:{p:"Ochs am Berg und Fangis.",e:"Versteinerlis, Fischer, Völkerball.",a:"Fahnenklau auf grossem Feld."}},
"craies":{t:"Himmel und Hölle und Kreidebild",desc:"Trottoir oder Terrasse werden zur riesigen Leinwand.",s:["Kreide hervorholen (oder selbst machen: Gips + Farbe).","Himmel und Hölle, eine Velostrecke oder ein Wandbild zeichnen.","Hüpfen oder auf den Zeichnungen Parcours machen.","Der Regen wischt alles weg: morgen das nächste Kunstwerk!"],v:{b:"Mit dicker Kreide kritzeln.",p:"Himmel und Hölle, Körperumrisse nachzeichnen.",e:"Strassenparcours für Velos, Trompe-l'œil."}},
"marionnettes":{t:"Sockenpuppen-Theater",desc:"Einzelne Socken werden zu Stars einer Vorstellung.",s:["Einzelne Socken sammeln.","Augen, Wollhaare und einen Filzmund aufkleben.","Ein Theater aus einer Schachtel oder hinter dem Sofa bauen.","Eine Geschichte erfinden und der Familie vorspielen."],v:{p:"Einfache Puppe, ein Lied oder Versli.",e:"Ein kleines Drehbuch mit mehreren Figuren schreiben."}},
"orchestre":{t:"Orchester aus Recycling-Instrumenten",desc:"Rasseln, Trommeln, Gummiband-Gitarren: bauen und dann im Konzert spielen.",s:["Rassel: Flasche + Reis. Trommel: Dose + gespannter Ballon.","Gitarre: Schuhschachtel + Gummibänder.","Ein Lied wählen und die Instrumente verteilen.","Konzert vor Publikum (oder den Kuscheltieren)!"],v:{b:"(Gut verschlossene) Rasseln zur Musik schütteln.",p:"Rassel und Trommel basteln, laut / leise spielen.",e:"Einen Rhythmus erfinden, Dirigentenspiel."}},
"impro":{t:"Improtheater-Abend",desc:"Gezogene Zettel: ein Ort, eine Figur, ein Gefühl… und Action!",s:["Zettel mit „Figuren“, „Orten“, „Gefühlen“ schreiben.","Von jedem einen ziehen und 2 Minuten improvisieren.","Die anderen raten oder wählen die beste Szene.","Schwieriger machen: in Reimen, in Zeitlupe…"],v:{e:"Einfache Figuren und Orte, Zweierszenen.",a:"Verrücktere Vorgaben, Impro-Matches im Team."}},
"escape":{t:"Escape Room zu Hause",desc:"45 Minuten, um aus dem Wohnzimmer zu entkommen: Rätsel, Codes und Schlösser.",s:["Eine Geschichte erfinden (Labor, Piraten, Spione).","4 bis 6 Rätsel erstellen, die je eine Zahl oder einen Hinweis liefern.","Rätsel verstecken und eine Schatztruhe vorbereiten (Schachtel, Vorhängeschloss).","Stoppuhr starten, bei Bedarf einen Tipp geben."],v:{e:"Bildrätsel, Bilderrätsel, versteckte Gegenstände.",a:"Cäsar-Code, Geheimtinte (Zitrone), Logik. Teenager können den Escape Room für die Jüngeren bauen!"}},
"jeu-invente":{t:"Eigenes Brettspiel erfinden",desc:"Spielbrett, Regeln, Karten: ein eigenes Spiel erschaffen und dann spielen.",s:["Ein Thema wählen (Dschungel, Weltall, die eigene Stadt).","Einen Parcours mit Spezialfeldern auf Karton zeichnen.","Figuren (Deckel), Aufgabenkarten, Würfel basteln.","Regeln aufschreiben, testen, anpassen."],v:{e:"Persönliches Leiterspiel mit Aufgabenkarten.",a:"Strategiespiel mit Ressourcen oder eigenes Kartenspiel."}},
"bac-sensoriel":{t:"Sinneskiste",desc:"Reis, Teigwaren, Linsen und Utensilien: schütten, sortieren, verstecken, finden.",s:["Eine grosse Kiste mit Reis, Teigwaren oder Griess füllen.","Löffel, Becher, Trichter dazulegen.","Grosse Gegenstände zum Finden verstecken.","Ständige Aufsicht (keine verschluckbaren Kleinteile)."],v:{b:"Grosse Teigwaren und Utensilien, immer mit Erwachsenen.",p:"Nach Farben sortieren, versteckte Buchstaben suchen."}},
"transvasement":{t:"Wasser-Umschütt-Station",desc:"Ein Becken, Gefässe, Schwämme: Konzentration und Spritzer.",s:["Ein Becken mit Wasser auf einem Tuch (oder draussen).","Becher, Trichter, Schwämme, Pipetten.","Enten oder Gegenstände dazu, die schwimmen / sinken.","Nie allein beim Wasser lassen."],v:{b:"Spritzen, füllen und leeren.",p:"Schwimmt oder sinkt es? Vermutungen anstellen."}},
"peinture-doigts":{t:"Fingerfarben und Stempel",desc:"Hände, geschnitzte Kartoffeln, Korken: alles wird zum Pinsel.",s:["Tisch abdecken, altes T-Shirt anziehen.","Abwaschbare Farbe auf Tellern.","Stempel: halbierte Kartoffel, Korken, Schwämme.","Die Werke mit Klammern an einer Schnur ausstellen."],v:{b:"Essbare Farbe (Joghurt + Lebensmittelfarbe) für die Kleinsten.",p:"Handabdruck-Tiere, Kartoffelstempel."}},
"bulles":{t:"Riesenseifenblasen",desc:"Selbst gemachte Lauge und Schnurstäbe für Blasen grösser als die Kinder.",s:["1 L Wasser, 100 ml Spülmittel, 1 Löffel Zucker (oder Glyzerin) mischen.","Eine Schnurschlaufe zwischen zwei Stäbe binden.","Eintauchen, sanft öffnen, rückwärts gehen.","Lauge einige Stunden ruhen lassen = stabilere Blasen."],v:{b:"Blasen anschauen und fangen.",p:"Mit Trinkhalmen und Ringen pusten.",e:"Riesenblasen, Blase in der Blase.",a:"Rezepte testen und die Lebensdauer der Blasen messen."}},
"cerf-volant":{t:"Drachen bauen",desc:"Drinnen bauen, draussen steigen lassen, sobald es Wind hat.",s:["Zwei Stäbe (Bambus) kreuzen und zusammenbinden.","Plastiksack oder Packpapier als Raute spannen.","Einen Schwanz (Bänder) und eine lange Schnur an der Kreuzung befestigen.","Bei leichtem Wind auf einer offenen Wiese, fern von Stromleitungen."],v:{e:"Einfacher verzierter Rautendrachen.",a:"Delta- oder Kastendrachen, Stabilität vergleichen."}},
"fusee":{t:"Raketen aus Kartonrollen",desc:"Rollen, Spitzen und Flügel: eine Raumflotte zum Weiterspielen.",s:["WC-Rollen bemalen.","Eine Papierspitze und Kartonflügel anbringen.","Mit Bullaugen und Flammen aus Krepppapier verzieren.","Countdown… Start!"],v:{p:"Farbe und Kleber.",e:"Eine ganze Raumstation, Planeten aus Papier."}},
"avions":{t:"Papierflieger-Wettbewerb",desc:"Wer fliegt am weitesten, am längsten, am genauesten?",s:["Verschiedene Modelle falten (klassisch, Gleiter, Pfeil).","Eine Piste mit Klebeband am Boden markieren.","Drei Disziplinen: Distanz, Flugzeit, Ziel (Korb).","Den Flieger zwischen den Runden verbessern."],v:{p:"Erwachsene falten, das Kind verziert und wirft.",e:"3 Modelle vergleichen, Resultate notieren.",a:"Anspruchsvolle Faltungen recherchieren, Familienrekord."}},
"piquenique-int":{t:"Picknick drinnen",desc:"Tischtuch am Boden, gemeinsam gepackter Korb: Regen verhindert kein Picknick.",s:["Gemeinsam Sandwiches, Gemüsesticks und Früchte vorbereiten.","Ein Tischtuch auf dem Wohnzimmerboden ausbreiten.","Kuscheltiere einladen, sanfte Musik auflegen.","Picknickspiele: Rätsel, Geschichten."],v:{b:"Kleine Häppchen zum Greifen, Kuscheltiere eingeladen.",p:"Sandwiches mit Ausstechformen machen.",e:"Menü und Einkaufsliste zusammenstellen."}},
"histoire-tour":{t:"Reihum-Geschichte",desc:"Alle fügen einen Satz hinzu: Die Geschichte wird verrückt und urkomisch.",s:["Sich im Kreis hinsetzen.","Die erste Person sagt „Es war einmal…“.","Alle fügen einen Satz oder eine Wendung hinzu.","Option: Wörter ziehen, die vorkommen müssen."],v:{p:"Mit Bildern oder Gegenständen als Inspiration.",e:"Vorgegebene Wörter einbauen, Überraschungsende.",a:"Vorgegebene Genres (Krimi, Science-Fiction), Ergebnis aufschreiben."}},
"yoga":{t:"Tier-Yoga",desc:"Katze, Kobra, Flamingo: Haltungen, um spielerisch zur Ruhe zu kommen.",s:["Matten oder Tücher auf den Boden.","Abfolge: Katze, herabschauender Hund, Kobra, Flamingo, Schmetterling.","Die Tiergeräusche machen!","Zum Schluss der „Pfannkuchen“: hinlegen, still atmen."],v:{b:"Tiere auf dem Schoss eines Elternteils nachahmen.",p:"Erzählte Geschichte, in der jedes Tier eine Haltung ist.",e:"Eigene Abfolge erfinden, Gleichgewichtshaltungen halten."}},
"timesup":{t:"Wer bin ich? (Time's Up selbst gemacht)",desc:"Beschreiben, dann ein Wort, dann pantomimisch: Lachanfälle garantiert.",s:["Alle schreiben 5 Namen (Figuren, Tiere, Gegenstände) auf Zettel.","Teams ab 2. Runde 1: 30 Sek. frei beschreiben.","Runde 2: nur ein Wort. Runde 3: Pantomime.","Erratene Zettel zählen."],v:{e:"Einfache Wörter: Tiere, Berufe, Gegenstände.",a:"Persönlichkeiten, Filme, Begriffe."}},
"orientation":{t:"OL im Quartier",desc:"Eine handgezeichnete Karte, Posten zum Finden: Abenteuer in der Nähe.",s:["Eine Karte des Quartiers oder Parks zeichnen.","6 bis 10 Posten (Bäume, Bänke, Brunnen) mit je einer Frage markieren.","Teams mit der Karte, ohne Handy!","Zurück zum Start, Antworten kontrollieren."],v:{e:"Mit Erwachsenen, nahe und gut sichtbare Posten.",a:"Selbstständig zu zweit, Kompass, Zeitlimit."}},
"bingo-nature":{t:"Natur-Bingo",desc:"Ein Raster zum Abhaken: Feder, Schnecke, rotes Blatt… wer ruft zuerst Bingo?",s:["Ein 4×4-Raster mit Dingen zeichnen, die man draussen finden kann.","Spazieren gehen, Gesehenes abhaken.","Volle Reihe = „Bingo!“.","Je nach Jahreszeit anpassen (Pilze im Herbst, Knospen im Frühling)."],v:{p:"Raster mit Zeichnungen, 9 Felder.",e:"16 Felder, Geräusche und Gerüche dazunehmen."}},
"etoiles":{t:"Sternenbeobachtungs-Abend",desc:"Eine Decke, eine Thermosflasche, der Himmel: den Grossen Wagen finden und eigene Sternbilder erfinden.",s:["Einen klaren Abend wählen, weg von Lichtern.","Decken, warme Kleider, ein heisses Getränk.","Die Augen 10 Minuten gewöhnen lassen.","Grossen Wagen, Mond, einen Planeten finden; Sternbilder erfinden."],v:{e:"Den Himmel zeichnen, Sternschnuppen zählen.",a:"Sternkarte aus Papier, Polarstern finden, Mythologie."}},
"hotel-insectes":{t:"Insektenhotel",desc:"Eine Kiste mit Stängeln, Tannenzapfen und Holz: Unterschlupf für Marienkäfer und Wildbienen.",s:["Eine Holzkiste oder einen aufgeschnittenen Milchkarton nehmen.","Mit hohlen Stängeln, Tannenzapfen, Stroh, gebohrtem Holz füllen.","Mit Gitter oder Schnur fixieren.","An einem sonnigen, regengeschützten Ort aufstellen und beobachten."],v:{e:"Milchkarton-Version, Beobachtungsheft.",a:"Holzversion mit Bohrmaschine (begleitet), Artenstudie."}},
"semis":{t:"Mini-Gemüsegarten im Topf",desc:"Heute ein Samen, in ein paar Tagen ein Keimling: Magie, die man jeden Morgen beobachtet.",s:["Gelochte Joghurtbecher oder Eierschalen, Blumenerde.","Säen: Radiesli, Kresse, Bohnen, Basilikum.","Jeden Tag etwas giessen, ans Fenster stellen.","Tagebuch führen: Wachstum messen und zeichnen."],v:{b:"Erde anfassen, mit kleiner Giesskanne giessen.",p:"Bohne in Watte: Man sieht die Wurzeln!",e:"Wachstumstagebuch mit Messungen.",a:"Balkongarten, Kompost, Setzlinge umpflanzen."}},
"slime":{t:"Schleim selber machen",desc:"Glibberig, dehnbar, farbig: die Lieblingschemie der Kinder.",s:["100 ml weissen Leim mit Farbe und Glitzer mischen.","1 TL Natron dazugeben.","Nach und nach Kontaktlinsenflüssigkeit (Kochsalzlösung) unterrühren.","Kneten, bis nichts mehr klebt. Danach Hände waschen."],v:{e:"Glitzerschleim, Fluffy-Schleim (mit Rasierschaum)."}},
"arc-en-ciel":{t:"Der wandernde Regenbogen",desc:"Gläser mit farbigem Wasser und Haushaltspapier: Die Farben wandern und mischen sich.",s:["6 Gläser aufreihen; jedes zweite mit farbigem Wasser füllen (rot, gelb, blau).","Haushaltspapier zu Streifen falten, als Bogen zwischen die Gläser legen.","30 Min. bis 1 Std. warten.","Beobachten: Die leeren Gläser füllen sich mit neuen Farben!"],v:{p:"Vorhersagen, welche Farben entstehen.",e:"Kapillarwirkung erklären, Zeit messen."}},
"pluviometre":{t:"Eine Wetterstation bauen",desc:"Regenmesser, Windfahne, Tagebuch: macht aus einem Regentag ein Experiment.",s:["Den Hals einer Flasche abschneiden und als Trichter umgekehrt einsetzen.","Ein Lineal seitlich aufkleben.","Draussen gut verkeilt aufstellen.","Täglich ablesen und im Wettertagebuch notieren."],v:{e:"Regenmesser + Windfahne aus Karton.",a:"Grafik über einen Monat, mit Prognosen vergleichen."}},
"bowling":{t:"Flaschen-Bowling",desc:"10 Flaschen, ein Ball: Strike!",s:["Etwas Wasser oder Sand in PET-Flaschen füllen (Stabilität).","Verzieren (optional).","Im Dreieck am Ende des Gangs aufstellen.","Punkte zählen, abwechselnd spielen."],v:{b:"Einen grossen Ball rollen, umgefallene Flaschen bejubeln.",p:"Umgefallene Kegel zählen.",e:"Punktetabelle, Handicap für die Grossen."}},
"minigolf":{t:"Minigolf zu Hause",desc:"Tunnel, Brücken und Rampen aus Karton für einen Parcours durchs Haus.",s:["5 bis 9 Löcher bauen: liegende Becher, gelochte Schachteln.","Hindernisse: Bücher, Rollen, Rampen.","Schläger: Besen, Stock + Karton oder einfach die Hand.","Schlagtabelle: Wer am wenigsten braucht, gewinnt."],v:{p:"Ball mit der Hand schieben, 3 Löcher.",e:"Kompletter Parcours mit Namen für jedes Loch."}},
"freeze":{t:"Stopptanz und Reise nach Jerusalem",desc:"Musik: tanzen. Stille: Statue! Die einfachste Art, sich auszutoben.",s:["Fetzige Musik auflegen.","Eine erwachsene Person stoppt zufällig.","Wer sich noch bewegt, macht ein lustiges Pfand.","Variante: Reise nach Jerusalem, Spiegeltanz."],v:{b:"Auf dem Arm tanzen, gemeinsam anhalten.",p:"Vorgegebene Tier-Statuen.",e:"Reise nach Jerusalem, vorgegebene Statuen.",a:"Choreografie-Wettbewerb zu zweit."}},
"courrier":{t:"Überraschungsbrief für jemanden",desc:"Ein echter, verzierter Brief zum Verschicken: Grosseltern, Freund, Nachbarin.",s:["Den Empfänger wählen.","Zeichnen, kleben, schreiben (oder einem Erwachsenen diktieren).","Den Umschlag selbst basteln.","Gemeinsam zur Post bringen: gleich noch ein kleiner Ausflug."],v:{p:"Zeichnung + Handabdruck.",e:"Brief mit Rätsel oder Gedicht.",a:"Regelmässige Brieffreundschaft, Pop-up-Karte."}},
"carton-geant":{t:"Burg oder Roboter aus Riesenkarton",desc:"Ein grosser Karton genügt: schneiden, bemalen und tagelang darin spielen.",s:["Grosse Kartons besorgen (Haushaltgeräte, Geschäfte).","Türen, Fenster, Zinnen zeichnen; Erwachsene schneiden mit dem Japanmesser.","Bemalen und verzieren.","Spielen: Burg, Raumschiff, Laden, tragbarer Roboter."],v:{p:"Haus mit Klebern und Filzstiften verzieren.",e:"Burg mit Zugbrücke an Schnur, Roboterkostüm."}},
"tiedye":{t:"Batik-T-Shirts",desc:"Alte weisse T-Shirts + Textilfarbe = Einzelstücke.",s:["Weisse Baumwoll-T-Shirts, nass und ausgewrungen.","Falten, zur Spirale drehen, mit Gummibändern fixieren.","Farbe auftragen (Handschuhe!), am besten draussen.","24 Std. im Sack ruhen lassen, ausspülen, separat waschen."],v:{e:"Einfache Spirale, 2 Farben.",a:"Anspruchsvolle Muster, Stofftaschen und Socken gestalten."}},
"bracelets":{t:"Freundschaftsbänder und Perlen",desc:"Eine ruhige Beschäftigung für die Hände, die man stolz trägt.",s:["4 bis 6 Fäden à 80 cm schneiden.","Oben verknoten, am Tisch festkleben.","Den Grundknoten lernen (Anleitung auf Papier oder Eltern).","Ein Freundschaftsband verschenken."],v:{e:"Perlenarmbänder, einfacher 3er-Zopf.",a:"Chevron-Muster, Namen aus Buchstabenperlen."}},
"bd":{t:"Eigenen Comic zeichnen",desc:"Ein Held, ein Problem, eine Lösung: in 6 Bildern die eigene Geschichte erzählen.",s:["Eine Figur erfinden und ihr eine Superkraft (oder eine Schwäche) geben.","Ein Blatt in 6 Felder falten.","Mit Bleistift zeichnen, Sprechblasen dazu, nachziehen.","Mehrere Seiten zu einem Mini-Album binden."],v:{e:"6 Bilder, einfache Sprechblasen.",a:"Mehrseitiges Fanzine, für die Familie kopiert."}},
"radio":{t:"Familien-Radiosendung",desc:"Wetter, Interview mit Grosi, erfundene Werbung, Kolumne: eine Sendung mit dem Diktiergerät.",s:["Rubriken festlegen: Hausnachrichten, Wetter, Interview, erfundene Werbung.","Texte schreiben und proben.","In einem Durchgang mit einem hingelegten alten Handy aufnehmen (ohne draufzuschauen!).","Beim Essen abspielen oder den Grosseltern schicken."],v:{e:"Kurze Rubriken mit einer erwachsenen Produktionsleitung.",a:"Teenager machen alles: Skript, Interviews, Jingle."}},
"topchef":{t:"Familien-Kochduell",desc:"Ein Korb mit vorgegebenen Zutaten, ein Zeitlimit, eine Jury: an die Töpfe!",s:["3 bis 5 vorgegebene Zutaten wählen.","Teams, 45 Min. auf der Uhr.","Sorgfältig anrichten, der Jury präsentieren.","Noten: Geschmack, Kreativität, Präsentation."],v:{e:"Desserts ohne Backen, zu zweit mit Erwachsenen.",a:"Ganzes Gericht, Budget- oder Anti-Food-Waste-Vorgaben."}},
"bivouac":{t:"Zelten im Garten oder auf dem Balkon",desc:"Zelt, Stirnlampe und Geschichten: Abenteuer zwei Schritte vom Haus entfernt.",s:["Gemeinsam das Zelt (oder eine Tuchhöhle) aufstellen.","Ein Lageressen vorbereiten (Sandwiches, Marshmallows).","Taschenlampe: Schatten, Geschichten, der Nacht lauschen.","Draussen schlafen… oder mitten in der Nacht reingehen, zählt auch!"],v:{e:"Abend im Zelt, dann bei Bedarf drinnen schlafen.",a:"Ganze Nacht, Teenager bauen und führen das Lager."}},
"velo":{t:"Velotour mit Herausforderungen",desc:"Eine Runde mit Aufgaben unterwegs: Langsamfahren, Slalom, Schilder suchen.",s:["Velos, Helme, Leuchtwesten kontrollieren.","Einen Veloweg oder eine verkehrsfreie Route wählen.","Aufgaben: Langsamfahr-Rennen, Slalom zwischen Flaschen, Kühe zählen.","Zvieripause auf halbem Weg."],v:{p:"Laufvelo oder Kindersitz, kurze Strecke.",e:"Langsamfahr-Rennen, Slalom.",a:"Route vom Teenager auf einer Papierkarte geplant."}},
"ballon":{t:"Fussball oder Völkerball mit der Familie",desc:"Eltern gegen Kinder: zum Austoben und Lachen.",s:["Spielfeld mit Jacken oder Flaschen abstecken.","Gemischte Teams oder Eltern gegen Kinder.","Angepasste Regeln: Tore der Kleinen zählen doppelt.","Revanche… und Zvieri für die Sieger."],v:{e:"Völkerball, Penaltyschiessen.",a:"Turnier mit erfundenen Regeln (Völkerball mit 3 Teams)."}},
"cache-cache":{t:"Versteckis (Taschenlampen-Version)",desc:"Der Klassiker, oder abends im Dunkeln mit Taschenlampe.",s:["Verbotene Zonen festlegen.","Wer sucht, zählt bis 30.","Taschenlampen-Version: Licht aus, wer angeleuchtet wird, ist gefunden.","Variante Sardinen: Eine Person versteckt sich, wer sie findet, versteckt sich dazu."],v:{p:"Kurz zählen, einfache Verstecke.",e:"Sardinen, Taschenlampen-Version."}},
"memory":{t:"Selbst gemachtes Memory",desc:"Karten basteln und dann spielen: zwei Aktivitäten in einer.",s:["20 bis 30 gleich grosse Quadrate aus Karton schneiden.","Paare zeichnen (Tiere, Früchte, Familienmitglieder).","Verdeckt mischen.","Pro Zug 2 Karten aufdecken, Paare behalten."],v:{p:"6 Paare, grosse Zeichnungen.",e:"15 Paare, Themen (Flaggen, Gefühle)."}},
"comptines":{t:"Versli und Fingerspiele",desc:"„Das isch dä Duume“, „Hoppe hoppe Reiter“: Sprache, Rhythmus und Kuscheln.",s:["Baby auf dem Schoss, Gesicht zu dir.","Langsam mit Gesten singen.","Wiederholen: Das Baby freut sich im Voraus und lächelt.","Mit Kitzeln oder einer Umarmung abschliessen."],v:{b:"Einfache Gesten, sanfte Stimme, viele Wiederholungen.",p:"Das Kind macht die Gesten und schlägt Lieder vor."}},
"coucou":{t:"Guguseli und Spiegelspiel",desc:"Für die Kleinsten: Objektpermanenz und viel Lachen.",s:["Sich hinter einem Tuch verstecken: „Guguus!“.","Ein Spielzeug unter dem Tuch verstecken, das Baby suchen lassen.","Vor dem Spiegel: Grimassen, Gesichtsteile benennen.","Dem Rhythmus des Babys folgen, aufhören, wenn es müde wird."],v:{b:"Leichtes Tuch, bruchsicherer Spiegel, auf der Spieldecke."}},
"chasse-couleurs":{t:"Farbenjagd im Haus",desc:"„Bring mir 3 blaue Sachen!“: rennen, Farben lernen, aufräumen.",s:["Eine Farbe ansagen.","Die Kinder bringen einen Gegenstand in dieser Farbe.","Die Gegenstände nach Farben auf Haufen sortieren.","Zum Schluss räumen alle zurück, was sie gebracht haben (Bonus!)."],v:{b:"Farben zeigen und benennen.",p:"Farben, dann Formen (Kreis, Quadrat)."}},
"galets":{t:"Bemalte Steine",desc:"Marienkäfer, Monster, liebe Worte: zum Behalten oder Verstecken, damit andere sie finden.",s:["Glatte Steine sammeln, waschen und trocknen.","Eine Grundfarbe auftragen.","Mit Farbstift oder feinem Pinsel malen.","Lackieren (verdünnter Leim) und ausstellen oder im Park verstecken."],v:{p:"Marienkäfer, Gesichter.",e:"Monster, Mandalas, Tic-Tac-Toe mit Steinen.",a:"Botschaftssteine zum Verstecken in der Stadt („Rock Painting“)."}},
"ombres":{t:"Schattentheater",desc:"Eine Lampe, ein Leintuch, Silhouetten: magisch an einem Regenabend.",s:["Silhouetten aus schwarzem Karton schneiden, auf Spiesse kleben.","Ein weisses Tuch spannen, Lampe dahinter.","Licht löschen und eine Geschichte erzählen.","Bonus: Schatten mit den Händen (Hase, Wolf, Vogel)."],v:{p:"Handschatten, Tier erraten.",e:"Ganze Geschichte mit Kulissen."}},
"kim":{t:"Kimspiel (Gedächtnis, Geschmack, Tasten)",desc:"Mit verbundenen Augen: ein Lebensmittel, einen Gegenstand oder das Fehlende auf dem Tablett erraten.",s:["Seh-Kim: 10 Gegenstände auf einem Tablett, 30 Sek. anschauen, einen entfernen.","Schmeck-Kim: mit verbundenen Augen Zitrone, Schokolade, Apfel probieren…","Tast-Kim: Gegenstände in einem undurchsichtigen Sack.","Richtige Antworten zählen."],v:{p:"5 Gegenstände, den fehlenden finden.",e:"15 Gegenstände, oder Schmeck-Kim."}},
"soupe":{t:"Gemüsesuppe vom Markt",desc:"Aussuchen, schälen, pürieren: ideal bei Kälte, und Kinder essen lieber, was sie selbst gekocht haben.",s:["Gemüse aussuchen (wenn möglich auf dem Markt).","Waschen, schälen (Sparschäler), schneiden (altersgerechtes Messer).","25 Min. in Wasser oder Bouillon kochen.","Pürieren und mit Croûtons servieren."],v:{p:"Gemüse waschen, in die (kalte) Pfanne geben.",e:"Schälen und schneiden, würzen.",a:"Die eigene Signature-Suppe erfinden."}},
"crepes":{t:"Crêpes-Zvieri",desc:"Eier aufschlagen, schwingen, wenden: das festliche Zvieri schlechthin.",s:["250 g Mehl, 4 Eier, ½ L Milch, 1 Prise Salz, 50 g flüssige Butter.","Mit dem Schwingbesen schlagen (Kinder lieben es).","Backen durch Erwachsene oder Teenager.","Füllungs-Bar: Konfitüre, Schokolade, Zucker, Früchte."],v:{p:"Mehl einfüllen, schwingen.",e:"Abmessen, Eier aufschlagen.",a:"Crêpes in der Luft wenden, salzige Galettes zum Znacht."}},
"escargots":{t:"Schneckensafari nach dem Regen",desc:"Nach dem Schauer wimmelt der Garten: Schnecken, Würmer zum Beobachten (und Freilassen).",s:["Kurz nach oder während eines feinen Regens rausgehen.","Unter Blättern und am Fuss von Mauern suchen.","Schneckenrennen auf einem nassen Brett!","Alle dort freilassen, wo man sie gefunden hat."],v:{b:"Anschauen und mit einem Finger sanft berühren.",p:"Zählen, Häuschen vergleichen.",e:"Zeichnen, ein Schneckenrennen stoppen."}},
"labyrinthe":{t:"Kugellabyrinth aus Karton",desc:"Ein Schachteldeckel, Trinkhalme und eine Murmel: Denken und Geduld.",s:["Den Deckel einer Schuhschachtel nehmen.","Einen Weg mit Start und Ziel zeichnen.","Trinkhalme oder Kartonstreifen als Wände kleben, Fallen-Löcher schneiden.","Neigen, um die Murmel ins Ziel zu bringen."],v:{e:"Einfaches Labyrinth mit 2 Fallen."}},
"sable":{t:"Sandburgen und Flüsse",desc:"Strand, See oder Sandkasten: bauen, Kanäle graben, fluten!",s:["Kessel, Schaufeln, Becher, Wasser.","Gut nasser Sand für die Mauern.","Gräben und Flüsse graben, Wasser hineingiessen.","Mit Muscheln und Stöcken verzieren. Sonnencreme!"],v:{b:"Kessel füllen und leeren, immer beaufsichtigt.",p:"Sandkuchen, Türme.",e:"Burg mit Graben und Brücken.",a:"Sandskulptur zu einem Thema."}},
"carte-sons":{t:"Geräuschkarten-Spaziergang",desc:"Im Wald sitzen, die Augen schliessen und alles zeichnen, was man hört.",s:["Ein Blatt mit einem Kreuz in der Mitte (das bist du).","Hinsetzen, 2 Minuten die Augen schliessen.","Jedes Geräusch dort einzeichnen, wo man es hört (Vogel links, Bach vorne).","Die Karten in der Familie vergleichen."],v:{p:"Geräusche flüsternd benennen.",e:"Gezeichnete Geräuschkarte, Vögel bestimmen."}},
"cabane-foret":{t:"Waldhütte bauen",desc:"Totholz, Schnur, Laub: einen echten Unterschlupf bauen.",s:["Einen Baum oder liegenden Stamm als Stütze finden.","Lange tote Äste als Tipi oder Pultdach anlehnen.","Mit Reisig und Laub abdichten.","Testen: Passen zwei hinein? Falls verlangt, vor dem Gehen wieder abbauen."],v:{e:"Einfaches Tipi mit Erwachsenen.",a:"Regendichter Survival-Unterschlupf, Bundknoten."}},
"enquete":{t:"Krimidinner / Cluedo in echt",desc:"Ein Rätsel, Verdächtige, im Haus versteckte Hinweise: Wer hat das letzte Guetzli gegessen?",s:["Das Szenario schreiben: Opfer (ein Kuchen!), Verdächtige, Motiv.","Rollenblätter für alle Mitspielenden.","Hinweise in den Zimmern verstecken.","Verhöre, dann klagen alle an. Grosse Auflösung!"],v:{e:"Einfache Ermittlung, ein Elternteil als Spielleitung.",a:"Szenario von Teenagern für die ganze Familie geschrieben."}},
"origami":{t:"Origami",desc:"Ein Blatt, ein paar Falten: springender Frosch, Himmel und Hölle, Kranich.",s:["Quadratische Blätter (aus A4 schneiden).","Mit Himmel und Hölle oder dem Springfrosch beginnen.","Falten mit dem Fingernagel gut nachziehen.","Froschhüpf-Rennen!"],v:{e:"Himmel und Hölle, Frosch, Schiff.",a:"Kranich, modulare Schachteln, die 1000-Kraniche-Challenge."}},
"cartes":{t:"Kartenspiel-Turnier",desc:"Schwarzer Peter, Uno, Arschloch, Tschau Sepp: ein Kartenspiel und los.",s:["Ein Spiel wählen, das zum jüngsten Kind passt.","Regeln mit einer Proberunde erklären.","Punktetabelle auf Papier.","Wer gewinnt, wählt das nächste Spiel."],v:{p:"Schwarzer Peter, Memory mit Karten.",e:"Tschau Sepp, Uno, Elfer raus.",a:"Arschloch, Tarot, Jass!"}},
"reparation":{t:"Werkstatt „Auseinandernehmen und verstehen“",desc:"Ein alter Wecker, ein kaputtes Gerät: Schraubenzieher in die Hand und entdecken, was drin ist.",s:["Ein ausgedientes Gerät wählen, ausgesteckt, ohne Akku oder riskante Kondensatoren.","Schutzbrille, Schraubenzieher, Schälchen für die Schrauben.","Zerlegen, Teile benennen (Motor, Zahnräder, Magnete).","Aus den Teilen eine Skulptur oder einen Roboter bauen."],v:{e:"Begleitetes Zerlegen, Teile sortieren.",a:"Schaltkreise verstehen, einen einfachen Gegenstand reparieren."}},
"neige-fort":{t:"Schneefestung und Schneeballschlacht",desc:"Festung bauen, Munition lagern und die Schlacht beginnt!",s:["Zwei Lager abstecken.","Eine Schneemauer bauen (Eiswürfelschale oder Kessel als Form).","Einen Vorrat an Schneebällen machen.","Regeln: nicht ins Gesicht, kein Eis."],v:{e:"Mauern und Teamschlacht.",a:"Fahnenklau im Schnee."}},
"pate-modeler":{t:"Duftende Knete",desc:"Rezept aus der Pfanne, farbig und duftend (Vanille, Zitrone, Zimt).",s:["1 Tasse Mehl, ½ Tasse Salz, 1 EL Öl, 1 EL Natron, 1 Tasse Wasser, Farbe.","Unter Rühren erhitzen, bis eine Kugel entsteht (Erwachsene).","Abkühlen lassen, kneten, einen Duft beigeben.","Kuchen und Tiere formen; luftdicht aufbewahren."],v:{p:"Wallholz, Ausstechformen, kleine Kuchen.",e:"Fantasiewesen, eine ganze Szene."}},
"defi-sportif":{t:"Familien-Olympiade",desc:"Weitsprung, Sackhüpfen, Sockenwerfen: Kartonmedaillen für alle.",s:["5 Disziplinen passend zum Ort wählen (drinnen: Sockenwerfen, Balancieren).","Medaillen aus Karton basteln.","Handicaps, damit Kleine und Grosse ausgeglichen sind.","Siegerehrung mit Hymne."],v:{p:"Krabbelrennen, Ballwurf.",e:"Sackhüpfen, Staffel.",a:"Teenager organisieren und schiedsrichtern."}},
"collage-fantastique":{t:"Collage mit Fantasietieren",desc:"Ein Löwenkopf, Schmetterlingsflügel, Elefantenfüsse: alte Zeitschriften zerschneiden und Fabelwesen erfinden.",s:["Alte Zeitschriften, Prospekte und Kataloge sammeln.","Köpfe, Körper, Beine und Flügel von Tieren (oder Gegenständen!) ausschneiden.","Das verrückteste Wesen zusammensetzen und aufkleben.","Ihm einen Namen, einen Ruf und eine Superkraft geben."],v:{p:"Von Erwachsenen vorgeschnittene Formen, freies Kleben.",e:"Steckbrief des Wesens: Lebensraum, Nahrung.",a:"Eine Serie von Wesen für ein illustriertes Bestiarium."}},
"peinture-gonflante":{t:"Aufgehende Farbe aus der Mikrowelle",desc:"Mehl, Salz und Backpulver: malen, 30 Sekunden in die Mikrowelle… und das Bild wird dreidimensional!",s:["3 EL Mehl, 1 EL Salz, 1 EL Backpulver, Wasser und Farbe mischen (Joghurt-Konsistenz).","Jede Farbe in einen Beutel füllen, eine kleine Ecke abschneiden.","Auf dünnen Karton oder dickes Papier malen.","20 bis 30 Sek. in die Mikrowelle (Erwachsene): das Bild geht auf!"],v:{p:"Grosse Kleckse und Formen, Staunen garantiert.",e:"Wolken, Glace, Monster in 3D."}},
"mosaique-papier":{t:"Mosaik aus gerissenem Papier",desc:"Reissen, sortieren, kleben: eine ruhige Beschäftigung mit leuchtenden Bildern.",s:["Einen einfachen Umriss zeichnen (Fisch, Sonne, Haus).","Kleine Stücke aus farbigem Papier reissen.","Nach Farben in Schälchen sortieren.","Die Zeichnung Stück für Stück mit Leim füllen."],v:{p:"Grosse Stücke, Leimstift.",e:"Farbverläufe, Muster.",a:"Mosaik eines Porträts oder einer Landschaft."}},
"attrape-reves":{t:"Traumfänger",desc:"Ein Ring, zu einem Netz gewobene Wolle, Perlen und Federn: zum Aufhängen über dem Bett.",s:["Einen Ring aus einem Kartonteller schneiden (oder einen biegsamen Zweig zum Kreis biegen).","Wolle anknoten und im Zickzack zu einem Netz spannen.","Beim Weben Perlen auffädeln.","Unten Fäden mit Federn oder Bändern anhängen."],v:{e:"Einfaches Sternnetz.",a:"Traditionelles Netzmuster, Farben passend zum Zimmer."}},
"flipbook":{t:"Daumenkino",desc:"Ein Männchen, das rennt, wenn man die Seiten durchblättert: Zeichentrick ohne Bildschirm!",s:["20 bis 30 kleine Blätter zusammenheften (oder einen Haftnotizblock nehmen).","Auf die letzte Seite zeichnen, dann auf die vorherige das gleiche Bild leicht verändert.","So weiter bis zur ersten Seite.","Mit dem Daumen schnell durchblättern."],v:{e:"Hüpfender Ball, wachsende Blume.",a:"Kurze Geschichte mit mehreren Figuren."}},
"masques":{t:"Masken aus Kartontellern",desc:"Löwe, Fuchs, Superheld: ein Teller, etwas Farbe, und die Vorstellung kann beginnen.",s:["Augenlöcher in einen Kartonteller schneiden (für die Kleinen Erwachsene).","Bemalen und verzieren: Wolle als Mähne, Papier für die Ohren.","Zwei Löcher stechen und ein Gummiband oder eine Schnur befestigen.","Umzug oder kleines Maskentheater!"],v:{p:"Einfache Tiere, Kleber.",e:"Aufwändige Fasnachtsmasken mit Federn und Glitzer."}},
"fresque-geante":{t:"Riesiges Familien-Wandbild",desc:"Eine lange Papierrolle am Boden: die ganze Familie malt gemeinsam zu einem Thema.",s:["Ein langes Papier (Packpapier, Rückseite von Tapete) am Boden oder an der Wand ausrollen.","Ein Thema wählen: die Stadt, der Dschungel, der Meeresgrund.","Alle beginnen in ihrer Ecke, dann werden die Zeichnungen verbunden.","Das Wandbild im Gang aufhängen."],v:{b:"Fingerfarben in einer reservierten Ecke.",p:"Grosse Farbflächen und Stempel.",e:"Detaillierte Figuren und Kulissen.",a:"Schriftzüge, Perspektive, Inszenierung."}},
"bijoux-pates":{t:"Ketten und Kronen aus Teigwaren",desc:"Bemalte Teigwaren werden zu Prinzessinnen- oder Piratenschmuck.",s:["Hohle Teigwaren (Penne, Hörnli) bemalen und trocknen lassen.","Eine Schnur in der richtigen Länge abschneiden.","Teigwaren in Farbmustern auffädeln.","Zuknoten und stolz tragen (oder verschenken)."],v:{p:"Grosse Teigwaren, steifer Schnürsenkel zum einfachen Auffädeln.",e:"Kartonkrone mit aufgeklebten Teigwaren."}},
"tissage":{t:"Weben auf einem Kartonwebrahmen",desc:"Ein eingekerbter Karton, etwas Wolle: einen Mini-Teppich oder Untersetzer weben lernen.",s:["Oben und unten an einem rechteckigen Karton alle 1 cm Kerben schneiden.","Wolle senkrecht durch die Kerben spannen (die Kette).","Wolle abwechselnd drüber und drunter weben, Reihe für Reihe.","Andrücken, Farbe wechseln, dann Fäden abschneiden und verknoten."],v:{e:"Einfache Farbstreifen.",a:"Muster, Fransen, kleiner Wandteppich."}},
"personnages-nature":{t:"Figuren aus Kastanien und Eicheln",desc:"Ein Spaziergang zum Sammeln, dann Igel, Männchen und Waldtiere basteln.",s:["Kastanien, Eicheln, Tannenzapfen, Zweige, Blätter sammeln.","Kastanien anbohren (Erwachsene), um Zahnstocher hineinzustecken.","Zusammensetzen und kleben: Köpfe, Arme, Hüte aus Eichelhütchen.","Eine kleine Waldszene gestalten."],v:{p:"Tannenzapfen-Igel mit Augen aus Knete.",e:"Eine ganze Familie, ein kleines Rindenhaus."}},
"peinture-paille":{t:"Pustebilder mit dem Trinkhalm",desc:"Ein Tropfen flüssige Farbe, ein Trinkhalm, und pusten: Bäume, Monster und Feuerwerk entstehen.",s:["Farbe mit etwas Wasser verdünnen.","Einen Tropfen aufs Blatt geben.","Durch den Trinkhalm pusten, damit die Farbe läuft (pusten, nicht saugen!).","Nach dem Trocknen Augen, Blätter oder Blüten ergänzen."],v:{b:"Erwachsene pusten, das Kind schaut zu und berührt.",p:"Haarige Monster mit aufgeklebten Augen.",e:"Blühende Bäume, Feuerwerk."}},
"carnet-secret":{t:"Ein eigenes Geheimbuch binden",desc:"Kartonumschlag, genähte Seiten: ein einzigartiges, handgemachtes Tagebuch.",s:["8 bis 10 Blätter in der Mitte falten und ineinanderlegen.","Entlang des Falzes 3 Löcher stechen.","Mit Schnur nähen (einfacher Stich) und verknoten.","Einen verzierten Kartonumschlag aufkleben, ein Gummiband zum Verschliessen anbringen."],v:{e:"Reise- oder Ideenheft, Umschlag als Collage.",a:"Japanische Bindung, Skizzenbuch, Bullet Journal auf Papier."}},
"lave-lampe":{t:"Lavalampe selber machen",desc:"Öl, farbiges Wasser und eine Brausetablette: Blasen steigen auf und ab wie in einer Zauberlampe.",s:["Eine durchsichtige Flasche zu ¾ mit Öl füllen.","Mit farbigem Wasser auffüllen (es sinkt nach unten).","Ein Stück Brausetablette (z. B. Vitamin C) hineingeben.","Beobachten, dann mit einer Taschenlampe von unten beleuchten."],v:{p:"Beobachten und Farben benennen.",e:"Erklären: Öl und Wasser mischen sich nicht, das Gas hebt das Wasser."}},
"oeuf-flotte":{t:"Das schwimmende Ei",desc:"Im Leitungswasser sinkt es, im Salzwasser schwimmt es: die Magie der Dichte.",s:["Ein rohes Ei in ein Glas Wasser legen: es sinkt.","In einem 2. Glas 6 Löffel Salz auflösen.","Das Ei hineinlegen: es schwimmt!","Herausforderung: Süsswasser vorsichtig auf das Salzwasser giessen, damit das Ei in der Mitte schwebt."],v:{p:"Zuerst raten: sinkt oder schwimmt es?",e:"Andere Gegenstände testen, Resultate notieren."}},
"encre-invisible":{t:"Botschaften mit Geheimtinte",desc:"Zitronensaft, ein Wattestäbchen… und mit Wärme erscheint die geheime Botschaft.",s:["Eine Zitrone in eine Schale auspressen.","Mit einem in Saft getauchten Wattestäbchen eine Botschaft schreiben.","Trocknen lassen: die Botschaft verschwindet.","Sichtbar machen, indem man das Blatt nahe an eine warme Glühbirne hält oder bügelt (Erwachsene)."],v:{e:"Agentenbotschaften, geheime Schatzkarte.",a:"Zitrone, Milch, Essig vergleichen: welche Tinte funktioniert am besten?"}},
"chou-rouge":{t:"Rotkabis, der die Farbe wechselt",desc:"Rotkabissaft wird je nach Zugabe rosa, violett oder grün: ein echter pH-Indikator.",s:["Rotkabis schneiden, 15 Min. mit heissem Wasser bedecken (Erwachsene), den violetten Saft absieben.","Auf mehrere Gläser verteilen.","Zugeben: Essig, Zitrone, Natron, Seife, Wasser…","Einordnen: rosa = sauer, grün/blau = basisch."],v:{e:"Vor jeder Zugabe die Farbe vorhersagen.",a:"Vollständige pH-Skala, selbst gemachtes Indikatorpapier."}},
"fusee-eau":{t:"Wasserrakete",desc:"Eine Flasche, Wasser, eine Velopumpe: Start auf mehrere Meter Höhe!",s:["Kartonflügel auf eine 1,5-L-Flasche kleben.","Zu einem Drittel mit Wasser füllen, mit einem Korken verschliessen, durch den ein Ventil (Ballnadel) führt.","Kopfüber auf eine Startrampe stellen, auf einer grossen freien Fläche.","Pumpen (Erwachsene) und zurücktreten: Start!"],v:{e:"Rakete verzieren, Höhe schätzen.",a:"Ideale Wassermenge testen, Spitze und Fallschirm ergänzen."}},
"ballon-bicarbonate":{t:"Der Ballon, der sich selbst aufbläst",desc:"Natron im Ballon, Essig in der Flasche: er bläst sich ohne Pusten auf.",s:["3 cm Essig in eine Flasche giessen.","Mit einem Trichter 2 TL Natron in einen Ballon füllen.","Den Ballon über den Flaschenhals stülpen, ohne dass das Pulver hineinfällt.","Den Ballon aufrichten: das Pulver fällt, es schäumt und der Ballon bläst sich auf!"],v:{p:"Beobachten und zählen, bis er aufgeblasen ist.",e:"Verschiedene Mengen testen, Ballonumfang messen."}},
"ludion":{t:"Der Zaubertaucher (Flaschenteufel)",desc:"Flasche drücken: der Taucher sinkt. Loslassen: er steigt. Wie von Zauberhand!",s:["Eine PET-Flasche randvoll mit Wasser füllen.","Den Taucher basteln: eine Stiftkappe mit etwas Knete am Ende (sie soll gerade noch schwimmen).","In die Flasche geben und gut verschliessen.","Flasche drücken: er sinkt; loslassen: er steigt."],v:{e:"Den Taucher nach Belieben auf- und absteigen lassen.",a:"Die Kompression der Luft erklären (Prinzip des U-Boots)."}},
"cristaux":{t:"Salzkristalle züchten",desc:"Eine sehr salzige Lösung, eine Schnur, etwas Geduld: nach einigen Tagen erscheinen echte Kristalle.",s:["Salz in heissem Wasser (Erwachsene) auflösen, bis sich nichts mehr löst.","In ein Glas giessen, eine Schnur an einem quergelegten Bleistift hineinhängen.","An einen ruhigen Ort stellen.","Eine Woche lang täglich mit der Lupe beobachten."],v:{p:"Schnelle Version: Salzwasser auf schwarzem Papier, beim Trocknen erscheinen Kristalle.",e:"Beobachtungstagebuch mit Zeichnungen.",a:"Salz, Zucker und Alaun vergleichen, das Wachstum fotografieren."}},
"lait-magique":{t:"Die psychedelische Milch",desc:"Ein paar Tropfen Farbe auf Milch, ein Wattestäbchen mit Seife: die Farben explodieren und wirbeln.",s:["Vollmilch in einen tiefen Teller giessen.","Tropfen verschiedener Farben in die Mitte geben.","Ein Wattestäbchen in Spülmittel tauchen.","In die Mitte halten und die Farben tanzen sehen."],v:{p:"Mit anderen Farben wiederholen.",e:"Vollmilch und Magermilch vergleichen: warum ist es anders?"}},
"catapulte":{t:"Katapult aus Glacestielen",desc:"Glacestiele, Gummibänder und ein Löffel: bauen, dann Zielschiessen.",s:["7 Stiele stapeln und an beiden Enden mit Gummibändern zusammenbinden.","2 weitere Stiele zu einem V binden, den Stapel dazwischenschieben.","Einen Löffel oder Deckel am Ende des Arms befestigen.","Pompons oder Papierkügelchen auf ein Ziel schiessen."],v:{e:"Wettbewerb für Weite und Genauigkeit.",a:"Drehpunkt verschieben, messen und ein Diagramm erstellen."}},
"oobleck":{t:"Treibsand (Oobleck)",desc:"Maisstärke + Wasser: hart, wenn man draufschlägt, flüssig, wenn man es fliessen lässt. Faszinierend!",s:["2 Tassen Maisstärke und 1 Tasse Wasser (+ Farbe) mischen.","Fest mit der Faust draufschlagen: es ist hart!","Eine Handvoll nehmen und fliessen lassen: es ist flüssig.","Eine Kugel zwischen den Händen rollen, dann aufhören: sie zerfliesst."],v:{b:"Anfassen und kneten, unter Aufsicht (ungiftig).",p:"Kleine Spielsachen darin verstecken.",e:"Erklären: eine „nicht-newtonsche“ Flüssigkeit."}},
"voiture-ballon":{t:"Ballonauto",desc:"Karton, Deckel als Räder, ein Trinkhalm und ein Ballon: es fährt von allein!",s:["Ein Chassis aus Karton schneiden, 2 Trinkhalme quer aufkleben.","Spiesse durch die Halme stecken, Deckel als Räder an die Enden stecken.","Einen Ballon an einen Trinkhalm kleben, oben befestigen.","Durch den Halm aufblasen, auf den Boden stellen, loslassen!"],v:{e:"Autorennen im Gang.",a:"Distanz verbessern: Gewicht, Räder, Ballongrösse."}},
"boussole":{t:"Einen Kompass bauen",desc:"Eine an einem Magneten gestrichene Nadel, ein Blatt auf dem Wasser: sie zeigt nach Norden!",s:["Eine Nadel 30-mal in die gleiche Richtung über einen Magneten streichen (Erwachsene).","Ein Blatt oder einen Korken in eine Schüssel Wasser legen.","Die Nadel vorsichtig darauflegen.","Sie dreht sich und zeigt nach Norden: mit der Sonne oder einem echten Kompass prüfen."],v:{e:"Spiel: Norden im Haus finden.",a:"Das Erdmagnetfeld verstehen, eine eingenordete Karte zeichnen."}},
"prisme":{t:"Regenbogen mit einem Glas Wasser",desc:"Ein Glas Wasser in der Sonne und ein weisses Blatt: das Licht zerlegt sich in einen Regenbogen.",s:["Ein durchsichtiges Glas mit Wasser füllen.","An den Tischrand in die Sonne stellen (oder vor eine Taschenlampe).","Ein weisses Blatt auf den Boden legen und den Regenbogen suchen.","Ihn zeichnen und die Farben benennen."],v:{p:"Farben zählen und benennen.",e:"Mit einer CD oder einem Spiegel im Wasser versuchen."}},
"beurre":{t:"Butter schütteln",desc:"Rahm in ein Glas, abwechselnd tanzend schütteln… und schon ist es Butter!",s:["Ein Glas zur Hälfte mit sehr kaltem Vollrahm füllen, verschliessen.","Abwechselnd etwa 10 Min. schütteln (Musik an!).","Wenn sich eine Kugel bildet, die Buttermilch abgiessen.","Die Kugel mit kaltem Wasser spülen, salzen, aufs Brot streichen."],v:{p:"Beim Singen schütteln, probieren.",e:"Die Etappen beobachten: Schlagrahm, dann Butter."}},
"statique":{t:"Magische statische Elektrizität",desc:"Ein an den Haaren geriebener Ballon: er zieht Konfetti an, lässt Haare zu Berge stehen, rollt eine Dose.",s:["Einen Ballon aufblasen.","Kräftig an trockenen Haaren oder einem Wollpullover reiben.","In die Nähe kleiner Papierschnipsel halten: sie springen hoch!","Herausforderung: eine leere Dose rollen lassen, ohne sie zu berühren."],v:{p:"Haare zu Berge vor dem Spiegel, Lachanfälle.",e:"Dosenrennen, einen dünnen Wasserstrahl biegen."}},
"tresor-pirates":{t:"Piraten-Schatzsuche",desc:"Eine mit Tee gealterte Karte, ein X an der richtigen Stelle, Schokoladentaler zum Ausgraben.",s:["Eine Karte des Hauses oder Gartens zeichnen, zerknittern, in kalten Tee tauchen, trocknen.","Den Weg markieren („10 Schritte zum grossen Baum“) und das X.","Eine Truhe verstecken oder vergraben (verzierte Schachtel, Schokoladentaler).","Augenklappe und Kopftuch: die Piraten stechen in See!"],v:{p:"Karte mit einfachen Bildern, 3 Etappen.",e:"Kompass und Schritte zählen, Piratenrätsel."}},
"chasse-images":{t:"Bildersuche für die Kleinen",desc:"Jeder Hinweis ist eine Zeichnung eines Orts im Haus: Kleinkinder lieben es, loszurennen und zu suchen.",s:["4 bis 6 einfache Orte zeichnen: Kühlschrank, Bett, Badewanne, Sofa.","An jedem Ort die nächste Zeichnung verstecken.","Die erste Zeichnung geben: „Wo ist das?“.","Am Schluss: eine Umarmung, ein Kuscheltier oder ein kleines Zvieri."],v:{b:"2 oder 3 Hinweise, das Kind begleiten.",p:"6 Hinweise, das Kind liest die Zeichnungen allein."}},
"jeu-piste-foret":{t:"Schnitzeljagd im Wald",desc:"Pfeile aus Ästen, farbige Wollknoten an Bäumen: ein Team legt die Spur, das andere folgt ihr.",s:["Team 1 startet 10 Minuten früher und markiert die Spur: Pfeile aus Stöcken, Wolle an Ästen.","Es hinterlässt unterwegs Rätselbotschaften.","Team 2 folgt den Zeichen bis zum finalen Versteck.","Auf dem Rückweg wird die ganze Wolle eingesammelt (Wald sauber lassen)."],v:{e:"Einfache Zeichen, kurzer Weg mit Erwachsenen.",a:"Pfadfinder-Wegzeichen, längere Spur, Rollen tauschen."}},
"tresor-nuit":{t:"Schatzsuche mit Taschenlampe",desc:"Licht aus, leuchtende oder reflektierende Hinweise: das Haus wird geheimnisvoll.",s:["Hinweise auf Zettel schreiben (wenn möglich mit nachleuchtenden Klebern).","Im Haus verstecken.","Licht löschen, Taschenlampen verteilen.","Finaler Schatz: ein Märchenabend oder ein besonderes Dessert."],v:{p:"Hinweise als Bilder, Erwachsene dabei.",e:"Rätsel im Lampenschein, Schatten erraten."}},
"rallye-ville":{t:"Rätsel-Rallye im Dorf oder Quartier",desc:"Welches Datum ist auf dem Brunnen eingraviert? Wie viele Glocken hat der Kirchturm? Die Umgebung neu entdecken.",s:["10 Orte auswählen und zu jedem eine Frage vorbereiten (Tafeln, Jahreszahlen, Statuen, Schilder).","Ein Laufblatt mit Plan verteilen.","Teams zu Fuss, ohne Handy, mit Zeitlimit.","Gemeinsam korrigieren, die Sieger wählen das Znacht."],v:{e:"Kurzer, begleiteter Parcours.",a:"Selbstständig, mit codierten Rätseln und Skizzen."}},
"chasse-sens":{t:"Schatzsuche der 5 Sinne",desc:"Um den nächsten Hinweis zu finden, muss man riechen, schmecken, tasten, hören oder schauen.",s:["5 Etappen vorbereiten, eine pro Sinn: ein Gewürz riechen, etwas probieren, einen Gegenstand im Sack ertasten…","Jede richtige Antwort verrät das nächste Versteck.","Bei manchen Aufgaben mit verbundenen Augen.","Der Schatz: ein Zvieri für alle 5 Sinne."],v:{p:"Einfache Aufgaben: Zitrone, Schokolade, Kuscheltier.",e:"Gewürze, aufgenommene Geräusche aus dem Haus."}},
"geocache-maison":{t:"Eine eigene Schatzkiste verstecken",desc:"Eine wasserdichte Box mit Logbuch und kleinen Tauschschätzen, in der Natur für Familie oder Freunde versteckt.",s:["Eine luftdichte Dose nehmen, ein Heft, einen Stift und ein paar kleine Gegenstände hineinlegen.","Ein Versteck in einem Park oder Wald wählen (nicht auf Privatgrund).","Eine genaue Karte mit Orientierungspunkten zeichnen.","Die Karte Freunden geben: wer sie findet, schreibt etwas hinein und tauscht einen Gegenstand."],v:{e:"Nahes Versteck, Karte mit Zeichnungen.",a:"Koordinaten auf einer Papierkarte, Rätsel zum Versteck."}},
"chasse-alphabet":{t:"Alphabet-Jagd",desc:"Für jeden Buchstaben etwas finden: A wie Apfel, B wie Bürste… bis Z!",s:["Das Alphabet auf ein Blatt schreiben.","Im Haus oder draussen für jeden Buchstaben einen Gegenstand suchen.","Neben dem Buchstaben aufschreiben oder zeichnen.","Wer zuerst bei Z ist, gewinnt (oder alle machen die Liste zusammen)."],v:{p:"Nur die Buchstaben des eigenen Namens.",e:"Ganzes Alphabet gegen die Uhr."}},
"tresor-neige":{t:"Eisjuwelen im Schnee versteckt",desc:"Am Vorabend farbiges Wasser in Formen gefrieren lassen: am nächsten Tag Jagd auf „Edelsteine“ im Schnee.",s:["Am Vorabend: Eiswürfel- oder Muffinformen mit farbigem Wasser füllen, draussen oder im Tiefkühler gefrieren lassen.","Herauslösen und die Eisjuwelen im Schnee oder Garten verstecken.","Suche: wer findet die meisten Edelsteine?","In Regenbogenreihenfolge aufreihen und fotografieren."],v:{p:"Grosse, leuchtend farbige Juwelen, gut sichtbar.",e:"Jede Farbe gibt unterschiedlich viele Punkte."}}
};
